    CUDA_CHECK(cudaMemcpy(M->d_csc_host->i, M->csc->i,
                          M->csc->nnz * sizeof(QOCOInt),
                          cudaMemcpyHostToDevice));
    CUDA_CHECK(cudaMemcpy(M->d_csc_host->p, M->csc->p,
                          (M->csc->n + 1) * sizeof(QOCOInt),
                          cudaMemcpyHostToDevice));
