    SpMtv_kernel<<<(M->d_csc_host->n + 255) / 256, 256, 0, qoco_metric_stream>>>(M->d_csc, v, r);
    CUDA_CHECK(cudaGetLastError());
    CUDA_CHECK(qoco_complete_vector_operation());
